#!/usr/bin/env node
const fs = require('fs');
const path = require('path');

const args = process.argv.slice(2);
const fileArg = args.find(arg => arg.startsWith('--file='));
if (!fileArg) {
  console.error('ERROR: --file argument required');
  process.exit(1);
}
const filename = fileArg.split('=')[1];
const filePath = path.join(__dirname, filename);

if (fs.existsSync(filePath)) {
  const stats = fs.statSync(filePath);
  const firstLine = fs.readFileSync(filePath, 'utf8').split('\n')[0];
  console.warn(`WARNING: File ${filename} already exists (${stats.size} bytes)`);
  console.warn(`First line: "${firstLine}"`);
  console.warn('Consider using a different filename or PATCH instead of WRITE.');
} else {
  console.log('OK: File does not exist.');
}

